rep(T, "  u.act = { k: 'bash', b: t.i, phase: 'wind', t0: W.t, end: W.t + (B.wind || 0.25), why: why || '', body: !!body };", "  u.act = { k: 'bash', b: t.i, phase: 'wind', t0: W.t, end: W.t + (B.wind || 0.25), why: why || '', body: !!body, arm: !body && !!u.armShield };")
